package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import java.util.regex.*;
/** Two ordered operations read from public original measured quantities. */
public final class DecimalTwoStepStories {
 private DecimalTwoStepStories(){}
 public static final String REMAIN="decimalGroupsThenRemaining",SHARE="decimalCombineThenSharing";
 public static final List<Catalog.Skill> SKILLS=List.of(new Catalog.Skill(REMAIN,"소수 양을 모은 뒤 사용하기",6,1,1,"","decimalTwoStepRemain",1000,"decimalQuantityGroups,decimalQuantityRemaining","전체 양을 구한 뒤 사용한 양을 뺀다."),new Catalog.Skill(SHARE,"소수 양을 합쳐 똑같이 나누기",6,1,1,"","decimalTwoStepShare",1000,"decimalQuantityTotal,decimalQuantitySharing","두 양을 합친 뒤 똑같이 나눈다."));
 public record Givens(String first,String second,int groups,String unit,boolean remaining){}
 public static boolean supports(String id){return REMAIN.equals(id)||SHARE.equals(id);}
 public static String prompt(String id,String x,String y,int k,String u){boolean remain=REMAIN.equals(id);if(remain)return u.equals("m")?"길이가 "+x+" m인 끈 "+k+"개를 잇고 "+y+" m를 잘라 냈습니다.\n남은 끈은 몇 m인가요?":u.equals("L")?"물 "+x+" L씩 든 통 "+k+"개의 물을 모아 "+y+" L를 사용했습니다.\n남은 물은 몇 L인가요?":"쌀 "+x+" kg씩 든 봉지 "+k+"개의 쌀을 모아 "+y+" kg을 사용했습니다.\n남은 쌀은 몇 kg인가요?";return u.equals("m")?"끈 "+x+" m와 "+y+" m를 잇고 길이가 같은 "+k+"조각으로 나눕니다.\n한 조각은 몇 m인가요?":u.equals("L")?"물 "+x+" L와 "+y+" L를 합쳐 "+k+"병에 똑같이 나눕니다.\n한 병에는 몇 L가 들어가나요?":"쌀 "+x+" kg과 "+y+" kg을 합쳐 "+k+"봉지에 똑같이 나눕니다.\n한 봉지에는 몇 kg이 들어가나요?";}
 public static Givens read(Question q){if(q==null||!supports(q.skillId)||q.prompt==null)return null;String num="(\\d{1,2}\\.\\d{1,3})",count="(\\d{1,2})";boolean remain=REMAIN.equals(q.skillId);for(String u:List.of("m","L","kg")){String template=prompt(q.skillId,"__X__","__Y__",1,u).replace("1","__K__"),pattern=Pattern.quote(template).replace("__X__","\\E"+num+"\\Q").replace("__Y__","\\E"+num+"\\Q").replace("__K__","\\E"+count+"\\Q");Matcher m=Pattern.compile(pattern).matcher(q.prompt);if(m.matches()){String x=m.group(1),y=m.group(remain?3:2);int k=Integer.parseInt(m.group(remain?2:3));if(k<1||remain&&new BigDecimal(x).multiply(BigDecimal.valueOf(k)).compareTo(new BigDecimal(y))<0)return null;return new Givens(x,y,k,u,remain);}}return null;}
 static BigDecimal firstResult(Givens v){BigDecimal x=new BigDecimal(v.first),y=new BigDecimal(v.second);return v.remaining?x.multiply(BigDecimal.valueOf(v.groups)):x.add(y);}
 static Rational result(Givens v){Rational first=Rational.decimal(firstResult(v).toPlainString());return v.remaining?first.sub(Rational.decimal(v.second)):first.div(Rational.of(v.groups));}
 static BigDecimal finite(Givens v){try{return v.remaining?firstResult(v).subtract(new BigDecimal(v.second)):firstResult(v).divide(BigDecimal.valueOf(v.groups));}catch(ArithmeticException nonterminating){return null;}}
 public static Question make(String id,String x,String y,int k,String u){if(!supports(id)||!Set.of("m","L","kg").contains(u)||k<1||k>99)throw new IllegalArgumentException("Selected two-step scope");Question q=new Question(id,prompt(id,x,y,k,u),"","");Givens v=read(q);if(v==null)throw new IllegalArgumentException("Selected two-step givens");BigDecimal value=finite(v);q.answers=new String[]{value==null?result(v).toString():text(value)};q.answerFormat=value==null?"fraction":"decimalValue";q.decimal=true;q.stepSupport=false;attach(q);return q;}
 static Question create(Catalog.Skill s,Random random,CurriculumLimits l){int max=l.wholeMaximum(99),places=l.decimalPlaces(3);if(max<0||max>99||places<1||places>3)throw new IllegalArgumentException("Selected two-step supply");int px=1+random.nextInt(places),py=1+random.nextInt(places),k=1+random.nextInt(99);BigDecimal x=BigDecimal.valueOf(random.nextInt((max+1)*(int)Math.pow(10,px)),px),y=BigDecimal.valueOf(random.nextInt((max+1)*(int)Math.pow(10,py)),py);if(REMAIN.equals(s.id)){BigDecimal total=x.multiply(BigDecimal.valueOf(k));if(y.compareTo(total)>0)y=total.setScale(py,RoundingMode.DOWN);}return make(s.id,x.toPlainString(),y.toPlainString(),k,List.of("m","L","kg").get(random.nextInt(3)));}
 static Checker.Result check(Question q,List<String> answers){Givens v=read(q);if(v==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"문제의 양 확인 필요");if(answers==null||answers.size()!=1||answers.get(0)==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"답 입력 필요");String raw=Expression.normalize(answers.get(0).trim());boolean fraction=finite(v)==null;if(raw.length()>120||!raw.matches("[+-]?\\d+(?:\\.\\d+)?(?:/[+-]?\\d+)?"))return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"수로 입력 필요");if(fraction&&!raw.contains("/"))return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"분수로 입력 필요");if(!fraction&&raw.contains("/"))return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"소수로 입력 필요");try{boolean correct=Expression.number(raw).equals(result(v));return new Checker.Result(correct?Checker.Status.CORRECT:Checker.Status.WRONG_ANSWER,correct?-1:0,correct?"계산 확인 완료":"이 계산 확인");}catch(RuntimeException e){return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"수 입력 확인 필요");}}
 public static int errorPart(Question q,String raw){Givens v=read(q);if(v==null||raw==null||raw.length()>120||FractionInput.invalidPart(raw)!=0)return 0;String[] parts=FractionInput.parts(raw);BigInteger n=new BigInteger(parts[0]),d=new BigInteger(parts[1]);Rational expected=result(v);if(n.multiply(expected.d).equals(expected.n.multiply(d)))return 0;if(d.equals(expected.d))return 1;if(n.equals(expected.n))return 2;return 0;}
 public static void attach(Question q){Givens v=read(q);if(v==null)return;StudyGuide h=new StudyGuide().transfer(false);h.teachingVersion="decimal-two-step-v1";Map<String,String> options=new LinkedHashMap<>();options.put("mulSub","한 묶음의 양 × 묶음 수, 그다음 사용한 양 빼기");options.put("addDiv","두 양 더하기, 그다음 묶음 수로 나누기");h.choice("문장에 맞는 계산 순서를 고르세요.",options,v.remaining?"mulSub":"addDiv");step(h,"첫째 양을 쓰세요.","첫째 양 x = ",v.first,true);step(h,"둘째 양을 쓰세요.","둘째 양 y = ",v.second,true);step(h,"묶음 수를 쓰세요.","묶음 수 k = ",""+v.groups,false);BigDecimal first=firstResult(v);step(h,v.remaining?"한 묶음의 양에 묶음 수를 곱하세요.":"두 양을 더하세요.",v.remaining?"중간 양 P = x × k = ":"중간 양 P = x + y = ",first.toPlainString(),true);BigDecimal value=finite(v);if(value!=null){step(h,v.remaining?"중간 양에서 사용한 양을 빼세요.":"중간 양을 묶음 수로 나누세요.",v.remaining?"남은 양 R = P − y = ":"한 묶음의 양 R = P ÷ k = ",text(value),true);}else{int precision=first.scale(),scale=(int)Math.pow(10,precision),numerator=first.movePointRight(precision).intValue(),denominator=scale*v.groups,gcd=Generator.gcd(numerator,denominator);step(h,"두 원래 양의 소수 자릿수 중 더 긴 자릿수를 쓰세요.","소수 자릿수 p = ",""+precision,false);step(h,"소수 자릿수에 맞는 배수를 쓰세요.","자릿값 배수 u = ",""+scale,false);step(h,"중간 양의 소수점을 오른쪽으로 p칸 옮기세요.","분자 A = P × u = ",""+numerator,false);step(h,"배수에 묶음 수를 곱해 분모를 구하세요.","분모 D = u × k = ",""+denominator,false);step(h,"분자와 분모의 최대공약수를 구하세요.","최대공약수 g = gcd(A, D) = ",""+gcd,false);step(h,"분자를 최대공약수로 나누세요.","분자 n = A ÷ g = ",""+(numerator/gcd),false);step(h,"분모를 같은 최대공약수로 나누세요.","분모 b = D ÷ g = ",""+(denominator/gcd),false);h.fractionResult(10,11);}q.studyGuide=h;}
 private static String text(BigDecimal v){return v.stripTrailingZeros().toPlainString();}
 private static void step(StudyGuide h,String instruction,String before,String expected,boolean decimal){h.step(instruction,before,"",expected);if(decimal)h.frames.get(h.frames.size()-1).inputFormat="decimalValue";}
}
